import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"0051 — An unserved lane is withdrawn into its successor, not stacked beside it","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0051-an-unserved-lane-is-withdrawn-not-stacked.md","filePath":"spec/decisions/0051-an-unserved-lane-is-withdrawn-not-stacked.md"}'),o={name:"spec/decisions/0051-an-unserved-lane-is-withdrawn-not-stacked.md"};function r(i,e,d,h,c,l){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_0051-—-an-unserved-lane-is-withdrawn-into-its-successor-not-stacked-beside-it" tabindex="-1">0051 — An unserved lane is withdrawn into its successor, not stacked beside it <a class="header-anchor" href="#_0051-—-an-unserved-lane-is-withdrawn-into-its-successor-not-stacked-beside-it" aria-label="Permalink to &quot;0051 — An unserved lane is withdrawn into its successor, not stacked beside it&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-23</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./0049-a-form-versions-alone.html">Decision 0049</a> minted <code>forms.takoform.com/v1beta4</code> and removed the version segment from the Form Family group. Implementing it surfaced a constraint the record did not know about, and the constraint decides something the record left open.</p><p>There is exactly one current family. <code>currentformregistry.V3Current()</code> is generated from the candidate tree, and <code>LoadCatalog</code> refuses any Form the registry does not carry, so <strong>every runnable corpus installs the same family</strong>. A lane whose wire schema cannot describe that family therefore cannot be run at all — not &quot;runs with fewer checks&quot;, but has no corpus it can execute.</p><p>That was measured rather than reasoned about. With the family versionless, a v1beta2 self-test answers HTTP 400 on the first authenticated read, because the group pattern in that lane&#39;s wire schema requires a <code>/vN</code> segment the group no longer has.</p><p>So the three lanes could not coexist. The available moves were: keep a second, versioned family tree for the older lanes — which decision 0049 forbids in as many words; widen the older lanes&#39; grammars in place — which would leave three lanes accepting the same thing and nothing left for v1beta4 to be minted for; or withdraw them.</p><p>The measurement that settles it is what is actually served. Against takoform.com: <code>forms.takoform.com/v1beta1</code>&#39;s corpus, wire schema and FormRef schema answer <strong>200</strong>; every v1beta2 and v1beta3 identity answers <strong>404</strong>. Neither lane was ever served, so neither has a consumer whose expectations a withdrawal could break.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong><code>forms.takoform.com/v1beta2</code> and <code>forms.takoform.com/v1beta3</code> are withdrawn into <code>forms.takoform.com/v1beta4</code>.</strong> Their documents, wire schemas, discovery schemas, operation tables and corpora are removed; their identities stay in the lane ledger as retired, so neither name can ever be reused meaning something else; and everything they stated is stated by v1beta4, which is the only lane this project asks a host to implement today.</p><p>This is the same move <a href="./0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a> made for the pre-Beta epochs and the same sentence decision 0049 used for the family tree, applied to the thing it was next true of: <em>minting a fourth lane beside two unpublished ones is ceremony of exactly the kind that record exists to remove.</em></p><p><strong>Two lanes remain</strong>: <code>v1beta1</code>, published and retained, and <code>v1beta4</code>, current.</p><h2 id="what-this-does-not-do" tabindex="-1">What this does not do <a class="header-anchor" href="#what-this-does-not-do" aria-label="Permalink to &quot;What this does not do&quot;">​</a></h2><p>It does not discard what v1beta2 and v1beta3 were minted for. The Beta 2 hardening review&#39;s wire changes (decision 0046) and the mechanism declarations (decision 0048) are v1beta4&#39;s, unchanged and still measured — 124 required checks, the same list the withdrawn corpus carried, plus what this lane adds. A withdrawn lane loses its NAME, not its content.</p><p>It does not make the numbering contiguous, and it should not. <code>v1beta2</code> and <code>v1beta3</code> are burned: the ledger records them as retired with the reason, and a reader who finds one of those identities in an old document can learn what happened to it. Renumbering v1beta4 down to v1beta2 would make the ledger lie about which names have been minted.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>One runnable corpus measures the one current lane against the one current family, and the coupling that forced this — a corpus can only install the family the registry carries — is now stated rather than discovered.</p><p>The cost is that this project&#39;s lane numbering has gaps, and that two lanes&#39; worth of authoring was retired within days of being written. The alternative was three lanes where one does the work, two of which no host could run, which is a worse thing to leave in a specification than a gap in a number line.</p>',18)])])}const w=t(o,[["render",r]]);export{u as __pageData,w as default};
